// Parse Telegram message
const body = $input.first().json.body;
const message = body.message.text;
const chatId = body.message.chat.id;
const userId = body.message.from.id;
const userName = body.message.from.username || body.message.from.first_name || 'User';

// Extract command and parameters
const parts = message.split(' ');
const command = parts[0].toLowerCase();
const params = parts.slice(1);

return {
  command: command,
  params: params,
  chatId: chatId,
  userId: userId,
  userName: userName,
  fullMessage: message
};

// Validate create_task parameters
const params = $input.first().json.params;

if (params.length < 4) {
  return {
    valid: false,
    error: '❌ Invalid format!\nUsage: /create_task "title" "description" "priority" "assignee"'
  };
}

const priority = params[2].toLowerCase();
if (!['low', 'medium', 'high'].includes(priority)) {
  return {
    valid: false,
    error: '❌ Invalid priority!\nUse: Low, Medium, or High'
  };
}

return {
  valid: true,
  title: params[0].replace(/"/g, ''),
  description: params[1].replace(/"/g, ''),
  priority: priority.charAt(0).toUpperCase() + priority.slice(1),
  assignee: params[3].replace(/"/g, ''),
  status: 'Open',
  createdDate: new Date().toISOString(),
  updatedDate: new Date().toISOString()
};

// Validate update_task parameters
const params = $input.first().json.params;

if (params.length < 2) {
  return {
    valid: false,
    error: '❌ Invalid format!\nUsage: /update_task {task_id} "status" "notes"'
  };
}

const taskId = params[0];
if (isNaN(taskId)) {
  return {
    valid: false,
    error: '❌ Task ID must be a number!'
  };
}

const status = params[1].toLowerCase();
if (!['open', 'in progress', 'completed', 'on hold'].includes(status)) {
  return {
    valid: false,
    error: '❌ Invalid status!\nUse: Open, In Progress, Completed, or On Hold'
  };
}

return {
  valid: true,
  taskId: parseInt(taskId),
  status: status.charAt(0).toUpperCase() + status.slice(1),
  notes: params.slice(2).join(' ').replace(/"/g, ''),
  updatedDate: new Date().toISOString()
};

// Format task list for Telegram
const tasks = $input.first().json;

if (!tasks || tasks.length === 0) {
  return {
    formatted: '📋 No tasks found!'
  };
}

let taskList = '📋 <b>Current Tasks</b>\n\n';
let count = 0;

tasks.forEach(task => {
  if (task['Task ID'] && task['Title']) {
    taskList += `#${task['Task ID']} - ${task['Title']}\n`;
    taskList += `Status: ${task['Status'] || 'N/A'} | Priority: ${task['Priority'] || 'N/A'}\n`;
    taskList += `Assignee: ${task['Assignee'] || 'Unassigned'}\n\n`;
    count++;
  }
});

if (count === 0) {
  taskList = '📋 No valid tasks found!';
} else {
  taskList = `📋 <b>Current Tasks (${count} total)</b>\n\n` + taskList;
}

return {
  formatted: taskList
};

// Find and format single task status
const tasks = $input.first().json;
const lookingForId = parseInt($input.second().json.params[0]);

const task = tasks.find(t => parseInt(t['Task ID']) === lookingForId);

if (!task) {
  return {
    found: false,
    message: `❌ Task #${lookingForId} not found`
  };
}

const message = `📌 <b>Task Status</b> - ID #${task['Task ID']}\n\n` +
  `<b>Title:</b> ${task['Title']}\n` +
  `<b>Description:</b> ${task['Description'] || 'N/A'}\n` +
  `<b>Status:</b> ${task['Status'] || 'N/A'}\n` +
  `<b>Priority:</b> ${task['Priority'] || 'N/A'}\n` +
  `<b>Assignee:</b> ${task['Assignee'] || 'Unassigned'}\n\n` +
  `<b>Created:</b> ${task['Created Date'] || 'N/A'}\n` +
  `<b>Updated:</b> ${task['Updated Date'] || 'N/A'}\n` +
  `<b>Notes:</b> ${task['Notes'] || 'No notes'}`;

return {
  found: true,
  message: message
};

// Build success response for create_task
const task = $input.first().json;

const message = `✅ <b>Task Created Successfully!</b>\n\n` +
  `<b>Task ID:</b> ${task.valid ? Math.floor(Math.random() * 10000) : 'N/A'}\n` +
  `<b>Title:</b> ${task.title || 'N/A'}\n` +
  `<b>Description:</b> ${task.description || 'N/A'}\n` +
  `<b>Priority:</b> ${task.priority || 'N/A'}\n` +
  `<b>Assignee:</b> ${task.assignee || 'N/A'}\n` +
  `<b>Status:</b> ${task.status || 'Open'}\n` +
  `<b>Created:</b> ${new Date().toLocaleString()}`;

return {
  message: message,
  chatId: $input.second().json.chatId
};

// Handle validation errors
const validation = $input.first().json;

if (!validation.valid) {
  return {
    message: validation.error,
    chatId: $input.second().json.chatId,
    isError: true
  };
}

return {
  message: 'Processing...',
  chatId: $input.second().json.chatId,
  isError: false
};
